class AgentTest_register_student(unittest.TestCase):

    def setUp(self):
        self.registration_system = ClassRegistrationSystem()

    def test_register_student_1(self):
        student1 = {"name": "John", "major": "Computer Science"}
        student2 = {"name": "Bob", "major": "Mathematics"}
        self.registration_system.register_student(student1)
        self.assertEqual(self.registration_system.register_student(student2), 1)
        self.assertEqual(len(self.registration_system.students), 2)
        self.assertIn(student1, self.registration_system.students)
        self.assertIn(student2, self.registration_system.students)
